mapper.select:
SELECT (select nvl(sum(ccc.due_amount),0) from con_contract_cashflow ccc where ccc.contract_id = cfr.contract_id and ccc.cf_item in (1, 10)) as old_due_amount, --调息前租金 (select nvl(sum(pqc.due_amount),0) from prj_quotation_cashflow pqc where pqc.quotation_id = cfr.quotation_id_new and cf_item in (1, 10)) as new_due_amount, --调息后租金 (select nvl(sum(ccc.principal),0) from con_contract_cashflow ccc where ccc.contract_id = cfr.contract_id and ccc.cf_item in (1, 10)) as old_principal, --调息前本金 (select nvl(sum(pqc.principal),0) from prj_quotation_cashflow pqc where pqc.quotation_id = cfr.quotation_id_new and pqc.cf_item in (1, 10)) as new_principal, --调息后本金 (select nvl(sum(ccc.interest),0) from con_contract_cashflow ccc where ccc.contract_id = cfr.contract_id and ccc.cf_item in (1, 10)) as old_interest, --调息前利息 (select nvl(sum(pqc.interest),0) from prj_quotation_cashflow pqc where pqc.quotation_id = cfr.quotation_id_new and pqc.cf_item in (1, 10)) as new_interest, --调后前利息 (select nvl(sum(ccc.interest),0) - nvl(sum(ccc.received_interest),0) from con_contract_cashflow ccc where ccc.contract_id = cfr.contract_id and ccc.cf_item in (1, 10)) old_outstanding_interest, --调息前剩余利息 ((select nvl(sum(pqc.interest),0) from prj_quotation_cashflow pqc where pqc.quotation_id = cfr.quotation_id_new and pqc.cf_item in (1 , 10)) - (select nvl(sum(ccc.received_interest),0) from con_contract_cashflow ccc where ccc.contract_id = cfr.contract_id and ccc.cf_item in (1 , 10) and EXISTS (select 1 from prj_quotation_cashflow pqc where pqc.quotation_id = cfr.quotation_id_new and pqc.cf_item in (1 , 10) ) -- and ccc.write_off_flag != 'NOT' ) ) new_outstanding_interest, --调息后剩余利息 ((select nvl(sum(pqc.interest), 0) from prj_quotation_cashflow pqc where pqc.quotation_id = cfr.quotation_id_new and pqc.cf_item in (1, 10)) - (select nvl(sum(ccc.interest), 0) from con_contract_cashflow ccc where ccc.contract_id = cfr.contract_id and ccc.cf_item in (1, 10) and EXISTS (select 1 from prj_quotation_cashflow pqc where pqc.quotation_id = cfr.quotation_id_new and pqc.cf_item in (1 , 10) )) ) as interest_adj_amount -- 利息差值
from con_floating_rate_req_ln cfr
1=1 and cfr.flt_req_ln_id = #{fltReqLnId}

select cfr.*
from con_floating_rate_req_ln cfr

      cfr.flt_req_id = #{fltReqId}
